360	// parseCheckpointRemoteFlag parses a "provider:owner/repo" string into its components.
361	// Supported providers: "github".
362	func parseCheckpointRemoteFlag(value string) (provider, repo string, err error) {
363		parts := strings.SplitN(value, ":", 2)
364		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
365			return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
366		}
367	
368		provider = parts[0]
369		repo = parts[1]
370	
371		switch provider {
372		case checkpointProviderGitHub:
373			// valid
374		default:
375			return "", "", fmt.Errorf("unsupported provider %q (supported: %s)", provider, checkpointProviderGitHub)
376		}
377	
378		repoParts := strings.SplitN(repo, "/", 2)
379		if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
380			return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
381		}
382	
383		return provider, repo, nil
384	}
