416	// hookAgentOptions builds selector options for every registered agent that
417	// supports hooks and isn't test-only (e.g. the Vogon canary), preselecting
418	// the names in selected.
419	func hookAgentOptions(selected map[types.AgentName]struct{}) []huh.Option[string] {
420		agentNames := agent.List()
421		options := make([]huh.Option[string], 0, len(agentNames))
422		for _, name := range agentNames {
423			ag, err := agent.Get(name)
424			if err != nil {
425				continue
426			}
427			if _, ok := agent.AsHookSupport(ag); !ok {
428				continue
429			}
430			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
431				continue
432			}
433			opt := huh.NewOption(string(ag.Type()), string(name))
434			if _, ok := selected[name]; ok {
435				opt = opt.Selected(true)
436			}
437			options = append(options, opt)
438		}
439		return options
440	}
