30	// handleFormCancellation handles cancellation from huh form prompts.
31	// User abort (Ctrl+C), timeout, and a cancelled/expired context (when the form
32	// ran via RunWithContext and the command's context was cancelled) all print a
33	// cancelled message and return nil. Other errors are wrapped with the action
34	// name for context.
35	func handleFormCancellation(w io.Writer, action string, err error) error {
36		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) ||
37			errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
38			fmt.Fprintf(w, "%s cancelled.\n", action)
39			return nil
40		}
41		return fmt.Errorf("%s prompt failed: %w", action, err)
42	}
